using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading.Tasks;using System.Security.Cryptography;using Newtonsoft.Json.Linq;using SpatialWallpaper.Sdk;using SpatialWallpaper.Sdk.Capabilities;
namespace SpatialWallpaper.Content {
