  public static async Task<JObject> ImportAsync(ContentStore store,string contentRoot,string dataRoot,string work){
   if(work!=LegacyMiniShotIdentity.NativeWork)throw new InvalidDataException("migration-native-work");string revision=store.Latest(work);var native=store.OpenNativeBuild(work,revision,NativeContentConfiguration.Platform());if(native.IsExternal||native.SceneId!="minishotgame")throw new InvalidDataException("migration-native-scene");
   var state=store.Snapshot;var sources=((JObject)state["works"]).Properties().Where(p=>(string)p.Value["default_build"]==LegacyMiniShotIdentity.Build&&(string)state["builds"][LegacyMiniShotIdentity.Build]?["kind"]=="sandbox-v4"&&(string)state["builds"][LegacyMiniShotIdentity.Build]?["archive_sha256"]==LegacyMiniShotIdentity.ArchiveSha256&&(string)store.Revision(p.Name,(string)p.Value["latest_revision"])["build_id"]==LegacyMiniShotIdentity.Build).ToArray();
   if(sources.Length!=1)throw new InvalidOperationException(sources.Length==0?"没有已安装且身份匹配的原版先行者 SDK 存档来源。":"多个旧版来源，不能猜测要导入的存档。");string oldWork=sources[0].Name,oldRevision=(string)sources[0].Value["latest_revision"];string archive;using(var original=store.OpenSandboxBuild(oldWork,oldRevision)){if(original.ArchiveSha256!=LegacyMiniShotIdentity.ArchiveSha256)throw new InvalidDataException("migration-original-digest");archive=original.Path;}
   string runtime=Path.Combine(Path.GetDirectoryName(UnityEngine.Application.dataPath),"native-runtime"),helper=Path.Combine(runtime,"supervisor","Supervisor.exe");Safe(helper);Safe(Path.Combine(runtime,"native-runtime.json"));var manifest=JsonData.Parse(File.ReadAllText(Path.Combine(runtime,"native-runtime.json")));if((string)manifest["sdk"]!="0.4.0-preview.1"||(int?)manifest["schema"]!=5||(int?)manifest["scene_command_abi"]!=1||Hash(helper)!=(string)manifest["files"]?["supervisor/Supervisor.exe"])throw new InvalidDataException("migration-helper-identity");
